          : keys[i] * 0 !== 0 || !!~('' + keys[i]).indexOf('.')
            ? {}
            : []
  }
}

import type { ZodError } from 'next/dist/compiled/zod'
import { ZodParsedType, util, type ZodIssue } from 'next/dist/compiled/zod'
import { fromZodError } from 'next/dist/compiled/zod-validation-error'
import * as Log from '../../build/output/log'

function processZodErrorMessage(issue: ZodIssue) {
  let message = issue.message

  let path: string

  if (issue.path.length > 0) {
    if (issue.path.length === 1) {
      const identifier = issue.path[0]
      if (typeof identifier === 'number') {
        // The first identifier inside path is a number
        path = `index ${identifier}`
      } else {
        path = `"${identifier}"`
      }
    } else {
      // joined path to be shown in the error message
      path = `"${issue.path.reduce<string>((acc, cur) => {
        if (typeof cur === 'number') {
          // array index
          return `${acc}[${cur}]`
        }
        if (cur.includes('"')) {
          // escape quotes
          return `${acc}["${cur.replaceAll('"', '\\"')}"]`
        }
        // dot notation
        const separator = acc.length === 0 ? '' : '.'
        return acc + separator + cur
      }, '')}"`
    }
  } else {
    path = ''
  }

  if (
    issue.code === 'invalid_type' &&
    issue.received === ZodParsedType.undefined
  ) {
    // Missing key in object.
    return `${path} is missing, expected ${issue.expected}`
  }

  if (issue.code === 'invalid_enum_value') {
    // Remove "Invalid enum value" prefix from zod default error message
    return `Expected ${util.joinValues(issue.options)}, received '${
      issue.received
    }' at ${path}`
  }

  return message + (path ? ` at ${path}` : '')
}

export function normalizeZodErrors(error: ZodError) {
  return error.issues.flatMap((issue) => {
    const issues = [{ issue, message: processZodErrorMessage(issue) }]
    if ('unionErrors' in issue) {
      for (const unionError of issue.unionErrors) {
        issues.push(...normalizeZodErrors(unionError))
      }
    }

    return issues
  })
}

export function formatZodError(prefix: string, error: ZodError) {
  return new Error(fromZodError(error, { prefix: prefix }).toString())
}

export function reportZodError(prefix: string, error: ZodError) {
  Log.error(formatZodError(prefix, error).message)
}

import { HTML_LIMITED_BOT_UA_RE } from './html-bots'

// Bot crawler that will spin up a headless browser and execute JS.
// Only the main Googlebot search crawler executes JavaScript, not other Google crawlers.
// x-ref: https://developers.google.com/search/docs/crawling-indexing/google-common-crawlers
// This regex specifically matches "Googlebot" but NOT "Mediapartners-Google", "AdsBot-Google", etc.
const HEADLESS_BROWSER_BOT_UA_RE = /Googlebot(?!-)|Googlebot$/i

export const HTML_LIMITED_BOT_UA_RE_STRING = HTML_LIMITED_BOT_UA_RE.source

export { HTML_LIMITED_BOT_UA_RE }

function isDomBotUA(userAgent: string) {
  return HEADLESS_BROWSER_BOT_UA_RE.test(userAgent)
}

function isHtmlLimitedBotUA(userAgent: string) {
  return HTML_LIMITED_BOT_UA_RE.test(userAgent)
}

export function isBot(userAgent: string): boolean {
  return isDomBotUA(userAgent) || isHtmlLimitedBotUA(userAgent)
}

export function getBotType(userAgent: string): 'dom' | 'html' | undefined {
  if (isDomBotUA(userAgent)) {
    return 'dom'
  }
  if (isHtmlLimitedBotUA(userAgent)) {
    return 'html'
  }
  return undefined
}

// This regex contains the bots that we need to do a blocking render for and can't safely stream the response
// due to how they parse the DOM. For example, they might explicitly check for metadata in the `head` tag, so we can't stream metadata tags after the `head` was sent.
// Note: The pattern [\w-]+-Google captures all Google crawlers with "-Google" suffix (e.g., Mediapartners-Google, AdsBot-Google, Storebot-Google)
// as well as crawlers starting with "Google-" (e.g., Google-PageRenderer, Google-InspectionTool)
export const HTML_LIMITED_BOT_UA_RE =
  /[\w-]+-Google|Google-[\w-]+|Chrome-Lighthouse|Slurp|DuckDuckBot|baiduspider|yandex|sogou|bitlybot|tumblr|vkShare|quora link preview|redditbot|ia_archiver|Bingbot|BingPreview|applebot|facebookexternalhit|facebookcatalog|Twitterbot|LinkedInBot|Slackbot|Discordbot|WhatsApp|SkypeUriPreview|Yeti|googleweblight/i

import fs from 'fs'
import path from 'path'

export function findDir(dir: string, name: 'pages' | 'app'): string | null {
  // prioritize ./${name} over ./src/${name}
  let curDir = path.join(dir, name)
  if (fs.existsSync(curDir)) return curDir

  curDir = path.join(dir, 'src', name)
  if (fs.existsSync(curDir)) return curDir

  return null
}

export function findPagesDir(dir: string): {
  pagesDir: string | undefined
  appDir: string | undefined
} {
  const pagesDir = findDir(dir, 'pages') || undefined
  const appDir = findDir(dir, 'app') || undefined

  if (appDir == null && pagesDir == null) {
    throw new Error(
      "> Couldn't find any `pages` or `app` directory. Please create one under the project root"
    )
  }

  if (pagesDir && appDir) {
    const pagesParent = path.dirname(pagesDir)
    const appParent = path.dirname(appDir)
    if (pagesParent !== appParent) {
      throw new Error(
        '> `pages` and `app` directories should be under the same folder'
      )
    }
  }

  return {
    pagesDir,
    appDir,
  }
}

import path from 'path'
import { pathToFileURL, fileURLToPath } from 'url'

/**
 * Converts a cache handler path to a filesystem path.
 * ESM's import.meta.resolve() returns file:// URLs which break when concatenated
 * with .next/ or used with path.join/path.relative.
 * @param filePath - Absolute path, relative path, or file:// URL (e.g. from import.meta.resolve)
 * @returns A filesystem path suitable for path operations
 */
export function resolveCacheHandlerPathToFilesystem(filePath: string): string {
  if (filePath.startsWith('file://')) {
    return fileURLToPath(filePath)
  }
  return filePath
}

/**
 * The path for a dynamic route must be URLs with a valid scheme.
 *
 * When an absolute Windows path is passed to it, it interprets the beginning of the path as a protocol (`C:`).
 * Therefore, it is important to always construct a complete path.
 * @param dir File directory
 * @param filePath Absolute or relative path, or file:// URL (e.g. from import.meta.resolve)
 */
export const formatDynamicImportPath = (dir: string, filePath: string) => {
  const resolvedFilePath = resolveCacheHandlerPathToFilesystem(filePath)

  const absoluteFilePath = path.isAbsolute(resolvedFilePath)
    ? resolvedFilePath
    : path.join(dir, resolvedFilePath)
  const formattedFilePath = pathToFileURL(absoluteFilePath).toString()

  return formattedFilePath
}

export function interopDefault<T>(mod: { default: T } | T): T {
  // @ts-ignore
  return mod.default || mod
}

// http://www.cse.yorku.ca/~oz/hash.html
// More specifically, 32-bit hash via djbxor
// (ref: https://gist.github.com/eplawless/52813b1d8ad9af510d85?permalink_comment_id=3367765#gistcomment-3367765)
// This is due to number type differences between rust for turbopack to js number types,
// where rust does not have easy way to repreesnt js's 53-bit float number type for the matching
// overflow behavior. This is more `correct` in terms of having canonical hash across different runtime / implementation
// as can gaurantee determinstic output from 32bit hash.
export function djb2Hash(str: string) {
  let hash = 5381
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i)
    hash = ((hash << 5) + hash + char) & 0xffffffff
  }
  return hash >>> 0
}

export function hexHash(str: string) {
  return djb2Hash(str).toString(36).slice(0, 5)
}

export class HardDeprecatedConfigError extends Error {
  constructor(message: string) {
    super(message)

    // This error is meant to interrupt the server start/build process
    // but the stack trace isn't meaningful, as it points to internal code.
    this.stack = undefined
  }
}

/// Utilties for configuring the bundler to use.
export enum Bundler {
  Turbopack,
  Webpack,
  Rspack,
}
/**
 * Parse the bundler arguments and potentially sets the `TURBOPACK` environment variable.
 *
 * NOTE: rspack is configured via next config which is chaotic so it is possible for this to be overridden later.
 *
 * @param options The options to parse.
 * @returns The bundler that was configured
 */
export function parseBundlerArgs(options: {
  turbo?: boolean
  turbopack?: boolean
  webpack?: boolean
}): Bundler {
  const bundlerFlags = new Map<Bundler, string[]>()
  const setBundlerFlag = (bundler: Bundler, flag: string) => {
    bundlerFlags.set(bundler, (bundlerFlags.get(bundler) ?? []).concat(flag))
  }
  // What turbo flag was set? We allow multiple to be set, which is silly but not ambiguous, just pick the most relevant one.
  if (options.turbopack) {
    setBundlerFlag(Bundler.Turbopack, '--turbopack')
  }
  if (options.turbo) {
    setBundlerFlag(Bundler.Turbopack, '--turbo')
  } else if (process.env.TURBOPACK) {
    // We don't really want to support this but it is trivial and not really confusing.
    // If we don't support it and someone sets it, we would have inconsistent behavior
    // since some parts of next would read the return value of this function and other
    // parts will read the env variable.
    setBundlerFlag(Bundler.Turbopack, `TURBOPACK=${process.env.TURBOPACK}`)
  } else if (process.env.IS_TURBOPACK_TEST) {
    setBundlerFlag(
      Bundler.Turbopack,
      `IS_TURBOPACK_TEST=${process.env.IS_TURBOPACK_TEST}`
    )
  }
  if (options.webpack) {
    setBundlerFlag(Bundler.Webpack, '--webpack')
  }

  if (process.env.IS_WEBPACK_TEST) {
    setBundlerFlag(
      Bundler.Webpack,
      `IS_WEBPACK_TEST=${process.env.IS_WEBPACK_TEST}`
    )
  }

  // Mostly this is set via the NextConfig but it can also be set via the command line which is
  // common for testing.
  if (process.env.NEXT_RSPACK) {
    setBundlerFlag(Bundler.Rspack, `NEXT_RSPACK=${process.env.NEXT_RSPACK}`)
  }
  if (process.env.NEXT_TEST_USE_RSPACK) {
    setBundlerFlag(
      Bundler.Rspack,
      `NEXT_TEST_USE_RSPACK=${process.env.NEXT_TEST_USE_RSPACK}`
    )
  }

  if (bundlerFlags.size > 1) {
    console.error(
      `Multiple bundler flags set: ${Array.from(bundlerFlags.values()).flat().join(', ')}.

Edit your command or your package.json script to configure only one bundler.`
    )
    process.exit(1)
  }
  // The default is turbopack when nothing is configured.
  if (bundlerFlags.size === 0) {
    process.env.TURBOPACK = 'auto'
    return Bundler.Turbopack
  }
  if (bundlerFlags.has(Bundler.Turbopack)) {
    // Only conditionally assign to the environment variable, preserving already set values.
    // If it was set to 'auto' because no flag was set and this function is called a second time we
    // would upgrade to '1' but we don't really want that.
    process.env.TURBOPACK ??= '1'
    return Bundler.Turbopack
  }
  // Otherwise it is one of rspack or webpack. At this point there must be exactly one key in the map.
  return bundlerFlags.keys().next().value!
}

/**
 * Finalize the bundler based on the config.
 *
 * Rspack is configured via next config by setting an environment variable (yay, side effects)
 * so this should only be called after parsing the config.
 */
export function finalizeBundlerFromConfig(fromOptions: Bundler) {
  // Reading the next config can set NEXT_RSPACK environment variables.
  if (process.env.NEXT_RSPACK) {
    return Bundler.Rspack
  }
  return fromOptions
}

import path from 'path'
import fs from 'fs'
import type { NextConfigComplete } from '../server/config-shared'
import * as Log from './output/log'
import { getTypeScriptConfiguration } from '../lib/typescript/getTypeScriptConfiguration'
import { readFileSync } from 'fs'
import isError from '../lib/is-error'
import { hasNecessaryDependencies } from '../lib/has-necessary-dependencies'
import { codeFrameColumns } from '../shared/lib/errors/code-frame'

let TSCONFIG_WARNED = false

export function parseJsonFile(filePath: string) {
  const JSON5 =
    require('next/dist/compiled/json5') as typeof import('next/dist/compiled/json5')
  const contents = readFileSync(filePath, 'utf8')

  // Special case an empty file
  if (contents.trim() === '') {
    return {}
  }

  try {
    return JSON5.parse(contents)
  } catch (err) {
    if (!isError(err)) throw err
    const codeFrame = codeFrameColumns(
      String(contents),
      {
        start: {
          line: (err as Error & { lineNumber?: number }).lineNumber || 1,
          column:
            (err as Error & { columnNumber?: number }).columnNumber ||
            undefined,
        },
      },
      { message: err.message, color: true }
    )
    throw new Error(
      `Failed to parse "${filePath}":\n${codeFrame ?? err.message}`
    )
  }
}

export type ResolvedBaseUrl =
  | { baseUrl: string; isImplicit: boolean }
  | undefined

export type JsConfig = { compilerOptions: Record<string, any> } | undefined

export default async function loadJsConfig(
  dir: string,
  config: NextConfigComplete
): Promise<{
  useTypeScript: boolean
  jsConfig: JsConfig
  jsConfigPath?: string
  resolvedBaseUrl: ResolvedBaseUrl
}> {
  let typeScriptPath: string | undefined
  try {
    const deps = hasNecessaryDependencies(dir, [
      {
        pkg: 'typescript',
        file: 'typescript/lib/typescript.js',
        exportsRestrict: true,
      },
    ])
    typeScriptPath = deps.resolved.get('typescript')
  } catch {}
  const tsConfigFileName = config.typescript.tsconfigPath || 'tsconfig.json'
  const tsConfigPath = path.join(dir, tsConfigFileName)
  const useTypeScript = Boolean(typeScriptPath && fs.existsSync(tsConfigPath))

  let implicitBaseurl
  let jsConfig: { compilerOptions: Record<string, any> } | undefined
  // jsconfig is a subset of tsconfig
  if (useTypeScript) {
    if (tsConfigFileName !== 'tsconfig.json' && TSCONFIG_WARNED === false) {
      TSCONFIG_WARNED = true
      Log.info(`Using tsconfig file: ${tsConfigFileName}`)
    }

    const ts = (await Promise.resolve(
      require(typeScriptPath!)
    )) as typeof import('typescript')
    const tsConfig = await getTypeScriptConfiguration(ts, tsConfigPath, true)
    jsConfig = { compilerOptions: tsConfig.options }
    implicitBaseurl = path.dirname(tsConfigPath)
  }

  const jsConfigPath = path.join(dir, 'jsconfig.json')
  if (!useTypeScript && fs.existsSync(jsConfigPath)) {
    jsConfig = parseJsonFile(jsConfigPath)
    implicitBaseurl = path.dirname(jsConfigPath)
  }

  let resolvedBaseUrl: ResolvedBaseUrl
  if (jsConfig?.compilerOptions?.baseUrl) {
    resolvedBaseUrl = {
      baseUrl: path.resolve(dir, jsConfig.compilerOptions.baseUrl),
      isImplicit: false,
    }
  } else {
    if (implicitBaseurl) {
      resolvedBaseUrl = {
        baseUrl: implicitBaseurl,
        isImplicit: true,
      }
    }
  }

  return {
    useTypeScript,
    jsConfig,
    resolvedBaseUrl,
    jsConfigPath: useTypeScript
      ? tsConfigPath
      : fs.existsSync(jsConfigPath)
        ? jsConfigPath
        : undefined,
  }
}

import { bold, cyan } from '../picocolors'
import os from 'os'
import path from 'path'
import semver from 'next/dist/compiled/semver'

import { FatalError } from '../fatal-error'
import isError from '../is-error'

function resolvePathAliasTarget(baseUrl: string, target: string): string {
  if (
    path.isAbsolute(target) ||
    target.startsWith('./') ||
    target.startsWith('../')
  ) {
    return target
  }

  if (baseUrl === '.' || baseUrl === './') {
    return `./${target}`
  }

  const resolvedTarget = path.join(baseUrl, target)
  if (
    path.isAbsolute(resolvedTarget) ||
    resolvedTarget.startsWith('./') ||
    resolvedTarget.startsWith('../')
  ) {
    return resolvedTarget
  }

  return `./${resolvedTarget}`
}

function rewritePathAliasesWithoutBaseUrl(
  baseUrl: string,
  originalPaths: unknown
): Record<string, unknown> {
  const rewrittenPaths: Record<string, unknown> =
    originalPaths && typeof originalPaths === 'object'
      ? Object.fromEntries(
          Object.entries(originalPaths).map(([key, values]) => [
            key,
            Array.isArray(values)
              ? values.map((value) =>
                  typeof value === 'string'
                    ? resolvePathAliasTarget(baseUrl, value)
                    : value
                )
              : values,
          ])
        )
      : {
          '*': [resolvePathAliasTarget(baseUrl, '*')],
        }

  if (!Object.prototype.hasOwnProperty.call(rewrittenPaths, '*')) {
    rewrittenPaths['*'] = [resolvePathAliasTarget(baseUrl, '*')]
  }

  return rewrittenPaths
}

function getNormalizedBaseUrlForPaths(
  baseUrl: string,
  tsConfigPath: string
): string {
  const tsConfigDir = path.resolve(path.dirname(tsConfigPath))
  const absoluteBaseUrl = path.isAbsolute(baseUrl)
    ? baseUrl
    : baseUrl.startsWith('./') || baseUrl.startsWith('../')
      ? path.resolve(tsConfigDir, baseUrl)
      : path.resolve(baseUrl)
  const relativeBaseUrl = path.relative(tsConfigDir, absoluteBaseUrl)

  return relativeBaseUrl || '.'
}

export async function getTypeScriptConfiguration(
  typescript: typeof import('typescript'),
  tsConfigPath: string,
  metaOnly?: boolean
): Promise<import('typescript').ParsedCommandLine> {
  try {
    const formatDiagnosticsHost: import('typescript').FormatDiagnosticsHost = {
      getCanonicalFileName: (fileName: string) => fileName,
      getCurrentDirectory: typescript.sys.getCurrentDirectory,
      getNewLine: () => os.EOL,
    }

    const { config, error } = typescript.readConfigFile(
      tsConfigPath,
      typescript.sys.readFile
    )
    if (error) {
      throw new FatalError(
        typescript.formatDiagnostic(error, formatDiagnosticsHost)
      )
    }

    let configToParse: any = config
    if (semver.gte(typescript.version, '6.0.0')) {
      const target = configToParse.compilerOptions?.target
      if (
        typeof target === 'string' &&
        (target.toLowerCase() === 'es3' || target.toLowerCase() === 'es5')
      ) {
        const { target: _target, ...restCompilerOptions } =
          configToParse.compilerOptions ?? {}

        // TypeScript 6 deprecates ES3/ES5 targets. Rewrite deprecated
        // targets in-memory to keep typechecking working without requiring
        // `ignoreDeprecations`.
        configToParse = {
          ...configToParse,
          compilerOptions: {
            ...restCompilerOptions,
            target: 'es2015',
          },
        }
      }

      const baseUrl = configToParse.compilerOptions?.baseUrl
      const hasBaseUrl = typeof baseUrl === 'string' && baseUrl.length > 0

      if (hasBaseUrl) {
        const rewrittenPaths = rewritePathAliasesWithoutBaseUrl(
          baseUrl,
          configToParse.compilerOptions?.paths
        )
        const { baseUrl: _baseUrl, ...restCompilerOptions } =
          configToParse.compilerOptions ?? {}

        // TypeScript 6 deprecates `baseUrl`; rewrite aliases to explicit
        // relative paths so path mapping still works without this option.
        configToParse = {
          ...configToParse,
          compilerOptions: {
            ...restCompilerOptions,
            paths: rewrittenPaths,
          },
        }
      }
    }

    const result = typescript.parseJsonConfigFileContent(
      configToParse,
      // When only interested in meta info,
      // avoid enumerating all files (for performance reasons)
      metaOnly
        ? {
            ...typescript.sys,
            readDirectory(_path, extensions, _excludes, _includes, _depth) {
              return [extensions ? `file${extensions[0]}` : `file.ts`]
            },
          }
        : typescript.sys,
      path.dirname(tsConfigPath)
    )

    if (semver.gte(typescript.version, '6.0.0')) {
      const parsedBaseUrl = result.options.baseUrl
      if (typeof parsedBaseUrl === 'string' && parsedBaseUrl.length > 0) {
        const normalizedBaseUrl = getNormalizedBaseUrlForPaths(
          parsedBaseUrl,
          tsConfigPath
        )

        // `baseUrl` can come from extended tsconfigs. Rewrite paths from the
        // fully-resolved baseUrl and remove it so TS6 deprecation checks do not
        // fail type checking.
        result.options.paths = rewritePathAliasesWithoutBaseUrl(
          normalizedBaseUrl,
          result.options.paths
        ) as import('typescript').MapLike<string[]>
        delete (result.options as { baseUrl?: unknown }).baseUrl
      }
    }

    if (result.errors) {
      result.errors = result.errors.filter(
        ({ code }) =>
          // No inputs were found in config file
          code !== 18003
      )
    }

    if (result.errors?.length) {
      throw new FatalError(
        typescript.formatDiagnostic(result.errors[0], formatDiagnosticsHost)
      )
    }

    return result
  } catch (err) {
    if (isError(err) && err.name === 'SyntaxError') {
      const reason = '\n' + (err.message ?? '')
      throw new FatalError(
        bold(
          'Could not parse' +
            cyan('tsconfig.json') +
            '.' +
            ' Please make sure it contains syntactically correct JSON.'
        ) + reason
      )
    }
    throw err
  }
}

import { isPlainObject } from '../shared/lib/is-plain-object'

// We allow some additional attached properties for Next.js errors
export interface NextError extends Error {
  type?: string
  page?: string
  code?: string | number
  cancelled?: boolean
  digest?: string
}

/**
 * This is a safe stringify function that handles circular references.
 * We're using a simpler version here to avoid introducing
 * the dependency `safe-stable-stringify` into production bundle.
 *
 * This helper is used both in development and production.
 */
function safeStringifyLite(obj: any) {
  const seen = new WeakSet()

  return JSON.stringify(obj, (_key, value) => {
    // If value is an object and already seen, replace with "[Circular]"
    if (typeof value === 'object' && value !== null) {
      if (seen.has(value)) {
        return '[Circular]'
      }
      seen.add(value)
    }
    return value
  })
}

/**
 * Checks whether the given value is a NextError.
 * This can be used to print a more detailed error message with properties like `code` & `digest`.
 */
export default function isError(err: unknown): err is NextError {
  return (
    typeof err === 'object' && err !== null && 'name' in err && 'message' in err
  )
}

export function getProperError(err: unknown): Error {
  if (isError(err)) {
    return err
  }

  if (process.env.NODE_ENV === 'development') {
    // provide better error for case where `throw undefined`
    // is called in development
    if (typeof err === 'undefined') {
      return new Error(
        'An undefined error was thrown, ' +
          'see here for more info: https://nextjs.org/docs/messages/threw-undefined'
      )
    }

    if (err === null) {
      return new Error(
        'A null error was thrown, ' +
          'see here for more info: https://nextjs.org/docs/messages/threw-undefined'
      )
    }
  }

  return new Error(isPlainObject(err) ? safeStringifyLite(err) : err + '')
}

export function getObjectClassLabel(value: any): string {
  return Object.prototype.toString.call(value)
}

export function isPlainObject(value: any): boolean {
  if (getObjectClassLabel(value) !== '[object Object]') {
    return false
  }

  const prototype = Object.getPrototypeOf(value)

  /**
   * this used to be previously:
   *
   * `return prototype === null || prototype === Object.prototype`
   *
   * but Edge Runtime expose Object from vm, being that kind of type-checking wrongly fail.
   *
   * It was changed to the current implementation since it's resilient to serialization.
   */
  return prototype === null || prototype.hasOwnProperty('isPrototypeOf')
}

import { existsSync, realpathSync } from 'fs'
import { resolveFrom } from './resolve-from'
import { dirname, join, relative } from 'path'

export interface MissingDependency {
  file: string
  /**
   * The package's package.json (e.g. require(`${pkg}/package.json`)) MUST resolve.
   * If `exportsRestrict` is false, `${file}` MUST also resolve.
   */
  pkg: string
  /**
   * If true, the pkg's package.json needs to be resolvable.
   * If true, will resolve `file` relative to the real path of the package.json.
   *
   * For example, `{ file: '@types/react/index.d.ts', pkg: '@types/react', exportsRestrict: true }`
   * will try to resolve '@types/react/package.json' first and then assume `@types/react/index.d.ts`
   * resolves to `path.join(dirname(resolvedPackageJsonPath), 'index.d.ts')`.
   *
   * If false, will resolve `file` relative to the baseDir.
   * ForFor example, `{ file: '@types/react/index.d.ts', pkg: '@types/react', exportsRestrict: true }`
   * will try to resolve `@types/react/index.d.ts` directly.
   */
  exportsRestrict: boolean
}

export type NecessaryDependencies = {
  resolved: Map<string, string>
  missing: MissingDependency[]
}

export function hasNecessaryDependencies(
  baseDir: string,
  requiredPackages: MissingDependency[]
): NecessaryDependencies {
  let resolutions = new Map<string, string>()
  const missingPackages: MissingDependency[] = []

  for (const p of requiredPackages) {
    try {
      const pkgPath = realpathSync(
        resolveFrom(baseDir, `${p.pkg}/package.json`)
      )
      const pkgDir = dirname(pkgPath)

      resolutions.set(join(p.pkg, 'package.json'), pkgPath)

      if (p.exportsRestrict) {
        const fileNameToVerify = relative(p.pkg, p.file)
        if (fileNameToVerify) {
          const fileToVerify = join(pkgDir, fileNameToVerify)
          if (existsSync(fileToVerify)) {
            resolutions.set(p.pkg, fileToVerify)
          } else {
            missingPackages.push(p)
            continue
          }
        } else {
          resolutions.set(p.pkg, pkgPath)
        }
      } else {
        resolutions.set(p.pkg, resolveFrom(baseDir, p.file))
      }
    } catch (_) {
      missingPackages.push(p)
      continue
    }
  }

  return {
    resolved: resolutions,
    missing: missingPackages,
  }
}

// source: https://github.com/sindresorhus/resolve-from
import path from 'path'
import isError from './is-error'
import { realpathSync } from './realpath'

const Module = require('module') as typeof import('module')

export const resolveFrom = (
  fromDirectory: string,
  moduleId: string,
  silent?: boolean
) => {
  if (typeof fromDirectory !== 'string') {
    throw new TypeError(
      `Expected \`fromDir\` to be of type \`string\`, got \`${typeof fromDirectory}\``
    )
  }

  if (typeof moduleId !== 'string') {
    throw new TypeError(
      `Expected \`moduleId\` to be of type \`string\`, got \`${typeof moduleId}\``
    )
  }

  try {
    fromDirectory = realpathSync(fromDirectory)
  } catch (error: unknown) {
    if (isError(error) && error.code === 'ENOENT') {
      fromDirectory = path.resolve(fromDirectory)
    } else if (silent) {
      return
    } else {
      throw error
    }
  }

  const fromFile = path.join(fromDirectory, 'noop.js')

  const resolveFileName = () =>
    // @ts-expect-error
    Module._resolveFilename(moduleId, {
      id: fromFile,
      filename: fromFile,
      paths:
        // @ts-expect-error
        Module._nodeModulePaths(fromDirectory),
    })

  if (silent) {
    try {
      return resolveFileName()
    } catch (error) {
      return
    }
  }

  return resolveFileName()
}

import fs from 'fs'

const isWindows = process.platform === 'win32'

// Interesting learning from this, that fs.realpathSync is 70x slower than fs.realpathSync.native:
// https://sun0day.github.io/blog/vite/why-vite4_3-is-faster.html#fs-realpathsync-issue
// https://github.com/nodejs/node/issues/2680
// However, we can't use fs.realpathSync.native on Windows due to behavior differences.
export const realpathSync = isWindows ? fs.realpathSync : fs.realpathSync.native

