const reportToTelemetry = ({ name, duration }: TraceEvent) => {
  const eventName = TRACE_EVENT_ACCESSLIST.get(name)
  if (!eventName) {
    return
  }
  const telemetry: Telemetry | undefined = traceGlobals.get('telemetry')
  if (!telemetry) {
    return
  }

  telemetry.record({
    eventName,
    payload: {
      durationInMicroseconds: duration,
    },
  })
}

